diff --git a/src/vs/workbench/contrib/chat/common/tools/builtinTools/runSubagentTool.ts b/src/vs/workbench/contrib/chat/common/tools/builtinTools/runSubagentTool.ts
index 23183977146db..71b197f80eaef 100644
--- a/src/vs/workbench/contrib/chat/common/tools/builtinTools/runSubagentTool.ts
+++ b/src/vs/workbench/contrib/chat/common/tools/builtinTools/runSubagentTool.ts
@@ -171,6 +171,7 @@ export class RunSubagentTool extends Disposable implements IToolImpl {
 			const effectiveSubAgentName = subAgentName ?? currentModeInstructions?.name;

 			if (subAgentName) {
+				this.validateSubagentAllowed(subAgentName, currentModeInstructions);
 				subagent = await this.getSubAgentByName(subAgentName);
 				if (subagent) {
 					// Check the pre-resolved model cache from prepareToolInvocation
@@ -205,7 +206,7 @@ export class RunSubagentTool extends Disposable implements IToolImpl {
 						name: subAgentName,
 						content: instructions.content,
 						toolReferences: this.languageModelToolsService.toToolReferences(instructions.toolReferences),
-						allowedSubagents: undefined,
+						allowedSubagents: subagent.agents,
 						metadata: instructions.metadata,
 						isBuiltin: isBuiltinAgent(subagent.source, subagent.uri, this.productService),
 					};
@@ -302,7 +303,7 @@ export class RunSubagentTool extends Disposable implements IToolImpl {
 			const variableSet = new ChatRequestVariableSet();
 			// When the extension is responsible for instruction collection, skip the core path entirely.
 			if (this.configurationService.getValue<boolean>(ChatConfiguration.CollectInstructionsInExtension) !== true) {
-				const computer = this.instantiationService.createInstance(ComputeAutomaticInstructions, ChatModeKind.Agent, modeTools, undefined, getChatSessionType(invocation.context.sessionResource));
+				const computer = this.instantiationService.createInstance(ComputeAutomaticInstructions, ChatModeKind.Agent, modeTools, modeInstructions?.allowedSubagents, getChatSessionType(invocation.context.sessionResource));
 				await computer.collect(variableSet, token);
 			}

@@ -552,9 +553,12 @@ export class RunSubagentTool extends Disposable implements IToolImpl {
 	async prepareToolInvocation(context: IToolInvocationPreparationContext, _token: CancellationToken): Promise<IPreparedToolInvocation | undefined> {
 		const args = context.parameters as IRunSubagentToolInputParams;
 		const requestedAgentName = this.normalizeRequestedAgentName(args.agentName);
+		const currentModeInstructions = context.chatSessionResource ? this.getCurrentModeInstructions(context.chatSessionResource) : undefined;

+		if (requestedAgentName) {
+			this.validateSubagentAllowed(requestedAgentName, currentModeInstructions);
+		}
 		const subagent = requestedAgentName ? await this.getSubAgentByName(requestedAgentName) : undefined;
-		const currentModeInstructions = context.chatSessionResource ? this.getCurrentModeInstructions(context.chatSessionResource) : undefined;

 		// Resolve the model early and cache it for invoke()
 		const resolved = this.resolveSubagentModel(subagent, context.modelId, args.model);
@@ -584,4 +588,11 @@ export class RunSubagentTool extends Disposable implements IToolImpl {
 		const model = this.chatService.getSession(sessionResource) as ChatModel | undefined;
 		return model?.getRequests().at(-1)?.modeInfo?.modeInstructions;
 	}
+
+	private validateSubagentAllowed(subAgentName: string, currentModeInstructions: IChatRequestModeInstructions | undefined): void {
+		const allowedSubagents = currentModeInstructions?.allowedSubagents;
+		if (allowedSubagents && !allowedSubagents.includes('*') && !allowedSubagents.includes(subAgentName)) {
+			throw new Error(`Requested agent '${subAgentName}' is not allowed by the current agent.`);
+		}
+	}
 }
diff --git a/src/vs/workbench/contrib/chat/test/common/tools/builtinTools/runSubagentTool.test.ts b/src/vs/workbench/contrib/chat/test/common/tools/builtinTools/runSubagentTool.test.ts
index 18f1eab4e027e..14e02b2f1f751 100644
--- a/src/vs/workbench/contrib/chat/test/common/tools/builtinTools/runSubagentTool.test.ts
+++ b/src/vs/workbench/contrib/chat/test/common/tools/builtinTools/runSubagentTool.test.ts
@@ -915,6 +915,155 @@ suite('RunSubagentTool', () => {
 		});
 	});

+	suite('subagent allowlist', () => {
+		let callIdCounter = 0;
+
+		function createAgent(name: string, agents?: readonly string[]): ICustomAgent {
+			const id = `file:///test/${name}.md`;
+			return {
+				id,
+				uri: URI.parse(id),
+				name,
+				description: `Agent ${name}`,
+				tools: ['tool1'],
+				agents,
+				agentInstructions: { content: `${name} instructions`, toolReferences: [] },
+				source: { storage: PromptsStorage.local },
+				target: Target.Undefined,
+				visibility: { userInvocable: true, agentInvocable: true },
+				enabled: true
+			};
+		}
+
+		function createAllowlistTool(opts: {
+			customAgents: ICustomAgent[];
+			currentModeInstructions: IChatRequestModeInstructions;
+			capturedRequests?: IChatAgentRequest[];
+		}) {
+			const mockToolsService = testDisposables.add(new MockLanguageModelToolsService());
+			const promptsService = new MockPromptsService();
+			promptsService.setCustomModes(opts.customAgents);
+
+			const mockChatAgentService: Pick<IChatAgentService, 'getDefaultAgent' | 'invokeAgent'> = {
+				getDefaultAgent() {
+					return { id: 'default-agent' } as IChatAgentService extends { getDefaultAgent(...args: infer _A): infer R } ? NonNullable<R> : never;
+				},
+				async invokeAgent(_id: string, request: IChatAgentRequest, _progress: (parts: IChatProgress[]) => void, _history: IChatAgentHistoryEntry[], _token: CancellationToken): Promise<IChatAgentResult> {
+					opts.capturedRequests?.push(request);
+					return {};
+				},
+			};
+
+			const mockChatService: Pick<IChatService, 'getSession'> = {
+				getSession() {
+					return {
+						getRequests: () => [{
+							id: 'req-1',
+							modeInfo: {
+								kind: undefined,
+								isBuiltin: false,
+								modeInstructions: opts.currentModeInstructions,
+								telemetryModeId: 'custom',
+								applyCodeBlockSuggestionId: undefined,
+							},
+						}],
+						acceptResponseProgress: () => { },
+					} as unknown as IChatModel;
+				},
+			};
+
+			const mockInstantiationService: Pick<IInstantiationService, 'createInstance'> = {
+				createInstance(..._args: never[]): { collect: () => Promise<void> } {
+					return { collect: async () => { } };
+				},
+			};
+
+			return testDisposables.add(new RunSubagentTool(
+				mockChatAgentService as IChatAgentService,
+				mockChatService as IChatService,
+				mockToolsService,
+				{} as ILanguageModelsService,
+				new NullLogService(),
+				new TestConfigurationService(),
+				promptsService,
+				mockInstantiationService as IInstantiationService,
+				{} as IProductService,
+			));
+		}
+
+		function createInvocation(agentName: string): IToolInvocation {
+			return {
+				callId: `allowlist-call-${++callIdCounter}`,
+				toolId: 'runSubagent',
+				parameters: { prompt: 'do something', description: 'test', agentName },
+				context: { sessionResource: URI.parse('test://session/allowlist') },
+				userSelectedTools: { runSubagent: true },
+			} as IToolInvocation;
+		}
+
+		const countTokens = async () => 0;
+		const noProgress: ToolProgress = { report() { } };
+
+		test('prepareToolInvocation rejects a requested agent outside the current allowlist', async () => {
+			const tool = createAllowlistTool({
+				customAgents: [createAgent('Allowed'), createAgent('Forbidden')],
+				currentModeInstructions: { name: 'Coordinator', content: 'Coordinate', toolReferences: [], allowedSubagents: ['Allowed'] },
+			});
+
+			await assert.rejects(
+				() => tool.prepareToolInvocation({
+					parameters: { prompt: 'test', description: 'test task', agentName: 'Forbidden' },
+					toolCallId: 'allowlist-prepare',
+					chatSessionResource: URI.parse('test://session/allowlist'),
+				}, CancellationToken.None),
+				(err: Error) => {
+					assert.ok(err.message.includes("Requested agent 'Forbidden' is not allowed"));
+					return true;
+				}
+			);
+		});
+
+		test('invoke rejects a requested agent outside the current allowlist', async () => {
+			const capturedRequests: IChatAgentRequest[] = [];
+			const tool = createAllowlistTool({
+				customAgents: [createAgent('Allowed'), createAgent('Forbidden')],
+				currentModeInstructions: { name: 'Coordinator', content: 'Coordinate', toolReferences: [], allowedSubagents: ['Allowed'] },
+				capturedRequests,
+			});
+
+			const result = await tool.invoke(createInvocation('Forbidden'), countTokens, noProgress, CancellationToken.None);
+
+			assert.deepStrictEqual({
+				requestCount: capturedRequests.length,
+				result: result.content[0].kind === 'text' ? result.content[0].value : undefined,
+			}, {
+				requestCount: 0,
+				result: "Error invoking subagent: Requested agent 'Forbidden' is not allowed by the current agent.",
+			});
+		});
+
+		test('invoke forwards the selected subagent allowlist to nested requests', async () => {
+			const capturedRequests: IChatAgentRequest[] = [];
+			const tool = createAllowlistTool({
+				customAgents: [createAgent('Allowed', ['Nested']), createAgent('Nested')],
+				currentModeInstructions: { name: 'Coordinator', content: 'Coordinate', toolReferences: [], allowedSubagents: ['Allowed'] },
+				capturedRequests,
+			});
+
+			await tool.invoke(createInvocation('Allowed'), countTokens, noProgress, CancellationToken.None);
+
+			assert.deepStrictEqual({
+				requestCount: capturedRequests.length,
+				subAgentName: capturedRequests[0]?.subAgentName,
+				allowedSubagents: capturedRequests[0]?.modeInstructions?.allowedSubagents,
+			}, {
+				requestCount: 1,
+				subAgentName: 'Allowed',
+				allowedSubagents: ['Nested'],
+			});
+		});
+	});
+
 	suite('nested subagent depth tracking', () => {
 		/**
 		 * Creates a RunSubagentTool with mocked services suitable for invoke() testing.

